<script>import{adminApi}from"../../services/adminApi";export default{data(){return{loading:true,d:{movements:[]}}},async mounted(){try{this.d=await adminApi.get("finance")}finally{this.loading=false}},methods:{money(v){return Number(v||0).toLocaleString("pt-BR",{style:"currency",currency:"BRL"})},date(v){return v?new Date(v).toLocaleString("pt-BR"):"—"}}}</script><template><div><h4>Financeiro</h4><p class="text-muted">Receita SaaS, volume do marketplace e histórico das movimentações.</p><div class="row"><div v-for="c in [{l:'Receita SaaS recebida',v:money(d.saasRevenue)},{l:'GMV de shows',v:money(d.gmv)},{l:'Receita marketplace',v:money(d.marketplaceRevenue)}]" :key="c.l" class="col-md-4"><div class="card"><div class="card-body"><p class="text-muted mb-1">{{c.l}}</p><h4>{{c.v}}</h4></div></div></div></div><div class="card"><div class="card-header"><h5 class="card-title mb-0">Movimentações</h5></div><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Data</th><th>Tipo</th><th>Descrição</th><th>Valor bruto</th><th>Receita Seven Shows</th><th>Status</th></tr></thead><tbody><tr v-for="x in d.movements" :key="x.id"><td>{{date(x.date)}}</td><td>{{x.type}}</td><td>{{x.description}}</td><td>{{money(x.gross)}}</td><td>{{money(x.platformRevenue)}}</td><td>{{x.status}}</td></tr></tbody></table></div></div></div></template>